        '<img src="' + esc(B(F.img)) + '" alt="' + esc(F.alt) + '" style="object-position:' + F.pos + '">' +
        '<div class="shade" aria-hidden="true"></div><span class="badge"><span class="dot"></span>' + esc(F.status) + '</span>' +
        '<div class="over" id="feat-desc"><div class="left"><div class="tags reveal">' + tags + '</div><h3>' + esc(F.title) + '</h3><span class="cta">Read the case study ↗</span></div>' +
        (imp ? '<div class="impact reveal"><b>' + esc(imp[0]) + '</b><span>' + esc(imp[1]) + '</span><small>' + esc(imp[2]) + '</small></div>' : '') + '</div></a>';
      q('#feat-below').innerHTML = '<a class="t" href="' + esc(F.href) + '"' + target + '><span>' + esc(F.title) + '</span><span>Read the case study ↗</span></a><div class="tags">' + tags + '</div>' +
        (imp ? '<p><b>' + esc(imp[0]) + '</b>  ' + esc(imp[1]) + ' <span style="color:var(--mute)">— ' + esc(imp[2]) + '</span></p>' : '');
      q('#sel-label').textContent = E.dir;
      q('#sel-grid').innerHTML = entry.selected.map(function (id) {
        var p = DATA.projects[id]; if (!p) { return ''; }
        var L = E.layout[id] || ['span 6', '3 / 2', '50% 50%'];
        return card(p, { col: L[0], ratio: L[1], pos: L[2], img: p.cardImg || p.img });
      }).join('');
      if (animate) {
        swaps += 1;
        app.querySelectorAll('[data-swap]').forEach(function (el) { el.classList.remove('swap-a', 'swap-b'); el.classList.add(swaps % 2 ? 'swap-a' : 'swap-b'); });
      }
